class Kendaraan {
  constructor(merek) {
    this.merek = merek;
    this.kecepatan = 0;
  }
  gas() {
    this.kecepatan += 10;
    return this.kecepatan;
  }
}
class MobilSport extends Kendaraan {
  constructor(merek, turbo) {
    super(merek);
    this.turbo = turbo;
  }
  gas() {
    super.gas();
    if (this.turbo) super.gas();
    return this.kecepatan;
  }
}
const m = new MobilSport("Ferrari", true);
m.gas();
console.log(m.gas());
console.log(m.merek);

